CREATE TABLE IF NOT EXISTS transform_runs (transform_run_id text PRIMARY KEY,caller_identity text NOT NULL,idempotency_key text NOT NULL,execution_mode text NOT NULL,contract_digest char(64) NOT NULL,plan_digest char(64) NOT NULL,status text NOT NULL,accepted_at timestamptz NOT NULL,heartbeat_at timestamptz NOT NULL,UNIQUE(caller_identity,idempotency_key));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_transform_run ON transform_runs ((true)) WHERE status NOT IN ('SUCCEEDED','FAILED','CANCELLED','ORPHANED');
CREATE TABLE IF NOT EXISTS batch_executions (batch_execution_id text PRIMARY KEY,transform_run_id text NOT NULL REFERENCES transform_runs,caller_identity text NOT NULL,idempotency_key text NOT NULL,batch_id text NOT NULL,authority text NOT NULL,model_fingerprint char(64) NOT NULL,status text NOT NULL,accepted_at timestamptz NOT NULL,started_at timestamptz,finished_at timestamptz,attempt integer NOT NULL,test_status text,failure_class text,heartbeat_at timestamptz NOT NULL,UNIQUE(caller_identity,idempotency_key));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_batch ON batch_executions(transform_run_id,batch_id) WHERE status NOT IN ('SUCCEEDED','FAILED','CANCELLED','ORPHANED');
CREATE TABLE IF NOT EXISTS batch_attempts (batch_attempt_id bigserial PRIMARY KEY,batch_execution_id text NOT NULL REFERENCES batch_executions,attempt integer NOT NULL,status text NOT NULL,heartbeat_at timestamptz NOT NULL,UNIQUE(batch_execution_id,attempt));
CREATE TABLE IF NOT EXISTS execution_events (event_id text PRIMARY KEY,transform_run_id text NOT NULL REFERENCES transform_runs,batch_execution_id text,event_type text NOT NULL,event_at timestamptz NOT NULL,metadata_json jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS execution_locks (lock_name text PRIMARY KEY,transform_run_id text NOT NULL REFERENCES transform_runs,acquired_at timestamptz NOT NULL,heartbeat_at timestamptz NOT NULL);
